                for rr in range(apex, -1, -1):
                    d = apex - rr
                    for cc in (c - d, c + d):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
            elif r + 1 < h and r + 1 != divider:
                out[r + 1][c] = 4
            elif r + 1 < h:
                out[r + 1][c] = 4
